def find_kth_sequence(n, k):
    # Helper function to calculate factorial
    def factorial(x):
        if x == 0 or x == 1:
            return 1
        result = 1
        for i in range(2, x + 1):
            result *= i
        return result

    # Helper function to calculate combinations
    def combinations(n, r):
        return factorial(n) // (factorial(r) * factorial(n - r))

    # Initialize the sequence
    sequence = []
    k -= 1  # Convert to zero-based index

    # Calculate the sequence
    for i in range(n - 1):
        for j in range(1, n):
            if j % n == 0:
                continue
            # Calculate the number of valid sequences starting with this prefix
            count = 0
            for m in range(1, n):
                if m % n == 0:
                    continue
                if i + 1 < n - 1:
                    count += combinations(n - i - 2, n - i - 2)
                else:
                    count += 1
            if k < count:
                sequence.append(j)
                break
            k -= count

    return sequence

